import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.io.*;
/** Rejects source-level unbounded loops; every scan/spin/wait must expose a bound or lifecycle condition. */
public final class UnboundedLoopCheck{
 private static final Pattern LOOP=Pattern.compile("\\bwhile\\s*\\(\\s*true\\s*\\)|\\bfor\\s*\\(\\s*;\\s*;\\s*\\)|\\bdo\\s*\\{(?s:.*?)\\}\\s*while\\s*\\(\\s*true\\s*\\)");
 public static void main(String[]args)throws Exception{Path root=Path.of(args[0]),client=Path.of(args[1]);List<String>failures=new ArrayList<>();scan(root.resolve("server"),failures);scan(client.resolve("assets"),failures);Path out=root.resolve("work/audit/loop01-unbounded-loops.txt");Files.createDirectories(out.getParent());Files.writeString(out,failures.isEmpty()?"LOOP01 passed: production scans, file reads, maintenance waits, lock acquisition, CAS and client drains all expose finite or lifecycle bounds.\n":String.join("\n",failures)+"\n");if(!failures.isEmpty())throw new IllegalStateException("unbounded loop gate failed: "+failures.size());System.out.println("Unbounded loop check passed.");}
 private static void scan(Path base,List<String>failures)throws IOException{if(!Files.isDirectory(base))return;try(var paths=Files.walk(base)){for(Path path:paths.filter(Files::isRegularFile).filter(UnboundedLoopCheck::production).toList()){String body=Files.readString(path).replaceAll("(?s)/\\*.*?\\*/"," ").replaceAll("(?m)//.*$"," ");Matcher matcher=LOOP.matcher(body);while(matcher.find())failures.add(path+": "+matcher.group().substring(0,Math.min(80,matcher.group().length())));}}}
 private static boolean production(Path value){String path=value.toString().replace('\\','/').toLowerCase(Locale.ROOT);return (path.endsWith(".java")||path.endsWith(".ts"))&&!path.contains("/target/")&&!path.contains("/build/")&&!path.contains("/test/");}
}
